import re

def parse(lines):
    hdr = re.compile(r'^(?P<fmri>svc:/\S+)(?:\s+\((?P<desc>.*)\))?\s*$')
    kv = re.compile(r'^\s*(?P<key>State|Reason|See|Impact):\s?(?P<value>.*)$')
    prompt = re.compile(r'^\S*[#$%>]\s*svcs\b|^\S+@\S+[#$%]')
    recs = []
    used = []
    skip = []
    cur = None
    last = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if prompt.search(l):
            skip.append(i)
            continue
        m = hdr.match(l)
        if m:
            cur = {'FMRI': m.group('fmri'), 'Description': m.group('desc') or '', 'State': '', 'Since': '', 'Reason': '', 'See': '', 'Impact': '', 'Dependents': ''}
            recs.append(cur)
            used.append(i)
            last = None
            continue
        if cur is None:
            continue
        m = kv.match(l)
        if m:
            k = m.group('key')
            v = m.group('value').strip()
            if k == 'State':
                sm = re.match(r'^(\S+)(?:\s+since\s+(.*))?$', v)
                if sm:
                    cur['State'] = sm.group(1)
                    cur['Since'] = sm.group(2) or ''
                else:
                    cur['State'] = v
            elif k == 'See':
                cur['See'] = (cur['See'] + '; ' + v) if cur['See'] else v
            else:
                cur[k] = v
            last = k
            used.append(i)
            continue
        if l[:1] in (' ', '\t') and last:
            v = l.strip()
            if last == 'Impact':
                cur['Dependents'] = (cur['Dependents'] + '; ' + v) if cur['Dependents'] else v
            elif last == 'See':
                cur['See'] = cur['See'] + '; ' + v
            elif last == 'State':
                cur['Since'] = (cur['Since'] + ' ' + v).strip()
            else:
                cur[last] = (cur[last] + ' ' + v).strip()
            used.append(i)
    blocks = []
    if recs:
        blocks.append({'name': 'services', 'kind': 'table', 'lines': used, 'records': recs})
    return {'blocks': blocks, 'skip': skip}
